 const form=document.querySelector('#answer-form');form.oninput=()=>{a.drafts[a.step]=readDraft(form);persist();};form.onchange=e=>{form.oninput();if(e.target.name==='section'){renderLesson();document.querySelector('[name=sign]')?.focus();}};
